SEARCH_HI = (
    '<p>PocketBudJet में दर्जनों फ़ीचर हैं — बेतरतीब ब्राउज़ करके सभी नहीं मिलेंगे। '
    'राशि या व्यापारी से लेनदेन खोजें। फ़ीचर खोजें: यात्रा ट्रैकिंग के लिए «mileage», '
    'वॉइस शॉर्टकट के लिए «voice», प्लानर के लिए «retirement» या एक्सेसिबिलिटी के लिए '
    '«colorblind» आज़माएँ। अगर सोचें कि PBJ कुछ कर सकता है, खोजें।</p>'
)


def main():
    text = FR.read_text(encoding='utf-8')
    for old, new in REPLACEMENTS:
        if old not in text:
            raise SystemExit(f'Missing expected fragment: {old[:80]!r}')
        text = text.replace(old, new, 1)

    text, n = re.subn(
        r'(<h3>कोई भी फ़ीचर तुरंत खोजें</h3>\s*)<p>.*?</p>',
        r'\1' + SEARCH_HI,
        text,
        count=1,
        flags=re.DOTALL,
    )
    if n != 1:
        raise SystemExit('Search-feature narration paragraph replace failed')

    OUT.parent.mkdir(parents=True, exist_ok=True)
    OUT.write_text(text, encoding='utf-8')
    print(f'Wrote {OUT}')


if __name__ == '__main__':
    main()
